test('a notice by text message is cut to 160 characters, ending in "..."', () => {
  const values = { title: 'A'.repeat(300), dueOn: '2026-11-27' };
  const full = composeNotice('dueSoon', { member: ADA, values }).body;
  const notice = composeNotice('dueSoon', { member: BEN, values });
  assert.equal(notice.body.length, 160);
  assert.ok(notice.body.endsWith('...'));
  assert.equal(notice.body.slice(0, 157), full.replace('Ada Okafor', 'Ben').slice(0, 157));
});

test('a text message of exactly 160 characters is left as it is', () => {
  const short = composeNotice('dueSoon', { member: BEN, values: { title: '', dueOn: '2026-11-27' } }).body;
  const title = 'B'.repeat(160 - short.length);
  const notice = composeNotice('dueSoon', { member: BEN, values: { title, dueOn: '2026-11-27' } });
  assert.equal(notice.body.length, 160);
  assert.ok(!notice.body.endsWith('...'));
});

test('a notice by email is never cut, however long', () => {
  const title = 'A'.repeat(300);
  const notice = composeNotice('dueSoon', { member: ADA, values: { title, dueOn: '2026-11-27' } });
  assert.ok(notice.body.length > 300);
  assert.ok(notice.body.includes(title));
});

